/* FizLab conceptual questions, ranking tasks and estimation tasks / Konceptualna pitanja, zadaci rangiranja i procjene */
(function () {
  'use strict';
  window.Content.registerConcepts([

    /* ---------- FORCES / SILE ---------- */
    { id: 'balloon-constant-speed', topic: 'forces', type: 'mc', level: 2,
      q: { en: 'A hot-air balloon rises at a constant speed. Gravity Fg and air resistance Fo act downward, buoyancy Fu acts upward. Which is true?',
           hr: 'Balon na vrući zrak diže se stalnom brzinom. Sila teža Fg i otpor zraka Fo djeluju prema dolje, a sila uzgona Fu prema gore. Što je točno?' },
      options: [ { en: 'Fu < Fg + Fo', hr: 'Fu < Fg + Fo' }, { en: 'Fu = Fg + Fo', hr: 'Fu = Fg + Fo' }, { en: 'Fu > Fg + Fo', hr: 'Fu > Fg + Fo' }, { en: 'Fu = Fg; air resistance does not matter', hr: 'Fu = Fg; otpor zraka nije važan' } ],
      answer: 1,
      explain: { en: 'Constant speed means the forces are balanced: the upward force equals the sum of the downward forces, Fu = Fg + Fo. If Fu were bigger, the balloon would speed up; if smaller, it would slow down.',
                 hr: 'Stalna brzina znači da su sile uravnotežene: sila prema gore jednaka je zbroju sila prema dolje, Fu = Fg + Fo. Da je Fu veća, balon bi ubrzavao; da je manja, usporavao bi.' },
      misconception: { en: 'Many think that to move upward the upward force must be bigger. But a bigger force would change the speed; steady motion needs zero net force.',
                       hr: 'Mnogi misle da za gibanje prema gore sila prema gore mora biti veća. No veća sila mijenjala bi brzinu; za jednoliko gibanje rezultanta mora biti nula.' } },

    { id: 'elevator-accelerating-up', topic: 'forces', type: 'mc', level: 2,
      q: { en: 'A person weighs 700 N. The elevator starts moving upward and speeds up. How hard does the floor push on the person\'s feet?',
           hr: 'Osoba ima težinu 700 N. Lift kreće prema gore i ubrzava. Kolikom silom pod gura stopala osobe?' },
      options: [ { en: 'less than 700 N', hr: 'manjom od 700 N' }, { en: 'exactly 700 N', hr: 'točno 700 N' }, { en: 'more than 700 N', hr: 'većom od 700 N' }, { en: 'zero, the elevator carries the person', hr: 'nulom, lift nosi osobu' } ],
      answer: 2,
      explain: { en: 'To speed up upward the net force on the person must point upward, so the floor must push with more than the weight. That is why you feel heavier when a lift starts going up.',
                 hr: 'Da bi osoba ubrzavala prema gore, rezultanta na nju mora biti usmjerena prema gore, pa pod mora gurati silom većom od težine. Zato se osjećaš težim kad lift kreće prema gore.' },
      misconception: { en: 'Pupils often believe the floor always pushes with exactly the weight. That is true only when the speed is constant or the lift stands still.',
                       hr: 'Učenici često misle da pod uvijek gura silom jednakom težini. To vrijedi samo kad je brzina stalna ili lift miruje.' } },

    { id: 'car-trailer-third-law', topic: 'forces', type: 'mc', level: 2,
      q: { en: 'A car pulls a trailer with a force of 1500 N and they speed up together. With what force does the trailer pull back on the car?',
           hr: 'Automobil vuče prikolicu silom 1500 N i zajedno ubrzavaju. Kolikom silom prikolica vuče automobil natrag?' },
      options: [ { en: '0 N, the trailer only follows', hr: '0 N, prikolica samo slijedi' }, { en: 'less than 1500 N, because the car is stronger', hr: 'manjom od 1500 N, jer je automobil jači' }, { en: 'exactly 1500 N', hr: 'točno 1500 N' }, { en: 'more than 1500 N', hr: 'većom od 1500 N' } ],
      answer: 2,
      explain: { en: 'Forces always come in pairs: the force of the car on the trailer and the force of the trailer on the car are equal and opposite (Newton\'s third law). They act on different bodies, so the car can still speed up: the road pushes the car forward harder than the trailer pulls it back.',
                 hr: 'Sile uvijek dolaze u paru: sila automobila na prikolicu i sila prikolice na automobil jednake su i suprotnog smjera (treći Newtonov zakon). Djeluju na različita tijela, pa automobil ipak ubrzava: cesta gura automobil naprijed jače nego što ga prikolica vuče natrag.' },
      misconception: { en: 'Many think the "stronger" or "active" body pulls harder. Interaction forces are always equal, even when one body speeds up and the other is dragged along.',
                       hr: 'Mnogi misle da "jače" ili "aktivno" tijelo vuče jače. Sile međudjelovanja uvijek su jednake, čak i kad jedno tijelo ubrzava, a drugo je vučeno.' } },

    { id: 'book-table-not-third-law-pair', topic: 'forces', type: 'mc', level: 3,
      q: { en: 'A book lies on a table. Earth pulls the book down with 10 N (its weight) and the table pushes the book up with 10 N. Are these two forces an action-reaction pair (Newton\'s third law)?',
           hr: 'Knjiga leži na stolu. Zemlja privlači knjigu prema dolje silom 10 N (težina), a stol gura knjigu prema gore silom 10 N. Jesu li te dvije sile par akcija-reakcija (treći Newtonov zakon)?' },
      options: [ { en: 'Yes, they are equal and opposite, so they are a pair.', hr: 'Da, jednake su i suprotne, pa su par.' }, { en: 'No, both act on the same body (the book); a third-law pair acts on two different bodies.', hr: 'Ne, obje djeluju na isto tijelo (knjigu); par iz trećeg zakona djeluje na dva različita tijela.' }, { en: 'Yes, because the book is at rest.', hr: 'Da, jer knjiga miruje.' }, { en: 'No, because the weight is bigger.', hr: 'Ne, jer je težina veća.' } ],
      answer: 1,
      explain: { en: 'Equal and opposite is not enough. A third-law pair acts on two different bodies: the table pushes the book up, and the book pushes the table down. Weight and the table\'s push both act on the book; they are balanced forces, which is why the book stays at rest.',
                 hr: 'Jednake i suprotne nije dovoljno. Par iz trećeg zakona djeluje na dva različita tijela: stol gura knjigu prema gore, a knjiga gura stol prema dolje. Težina i sila stola obje djeluju na knjigu; to su uravnotežene sile, i zato knjiga miruje.' },
      misconception: { en: 'The popular mistake is to call any two equal and opposite forces a "third-law pair". Balanced forces on one body and an interaction pair on two bodies are different things.',
                       hr: 'Česta je pogreška svake dvije jednake i suprotne sile nazvati "parom iz trećeg zakona". Uravnotežene sile na jednom tijelu i par međudjelovanja na dva tijela različite su stvari.' } },

    { id: 'dynamometer-two-pull', topic: 'forces', type: 'mc', level: 1,
      q: { en: 'A boy and a girl pull the two ends of a dynamometer in opposite directions, each with 100 N. It does not move. What does the dynamometer read?',
           hr: 'Dječak i djevojčica vuku dva kraja dinamometra u suprotnim smjerovima, svaki silom 100 N. Dinamometar se ne pomiče. Što pokazuje dinamometar?' },
      options: [ { en: '0 N', hr: '0 N' }, { en: '100 N', hr: '100 N' }, { en: '200 N', hr: '200 N' }, { en: '50 N', hr: '50 N' } ],
      answer: 1,
      explain: { en: 'A dynamometer measures the tension in its spring, and that tension is 100 N. The two pulls do not add up: each end is pulled with 100 N, exactly as if one end were tied to a wall.',
                 hr: 'Dinamometar mjeri napetost svoje opruge, a ona iznosi 100 N. Dvije sile se ne zbrajaju: svaki kraj vuče se silom 100 N, točno kao da je jedan kraj zavezan za zid.' },
      misconception: { en: 'Many add the two forces and expect 200 N. If that were right, a 100 N weight hanging on a dynamometer fixed to the ceiling would also read 200 N, because the ceiling pulls up with 100 N.',
                       hr: 'Mnogi zbroje dvije sile i očekuju 200 N. Da je to točno, uteg od 100 N na dinamometru pričvršćenom za strop također bi pokazivao 200 N, jer strop vuče prema gore silom 100 N.' } },

    { id: 'friction-adapts', topic: 'forces', type: 'mc', level: 3,
      q: { en: 'A heavy box rests on the floor. The biggest friction force the floor can give is 10 N. You push the box gently with 3 N and it does not move. How big is the friction force now?',
           hr: 'Teška kutija miruje na podu. Najveća sila trenja koju pod može dati iznosi 10 N. Lagano guraš kutiju silom 3 N i ona se ne pomiče. Kolika je sada sila trenja?' },
      options: [ { en: '10 N', hr: '10 N' }, { en: '3 N', hr: '3 N' }, { en: '0 N', hr: '0 N' }, { en: '7 N', hr: '7 N' } ],
      answer: 1,
      explain: { en: 'The box stays at rest, so the forces are balanced: friction is exactly 3 N, opposite to your push. Static friction adapts: it grows with your push, up to its maximum of 10 N. Only when you push harder than 10 N does the box start to slide.',
                 hr: 'Kutija miruje, pa su sile uravnotežene: trenje iznosi točno 3 N, suprotno tvojem guranju. Trenje mirovanja prilagođava se: raste s tvojom silom, do najviše 10 N. Tek kad guraš jače od 10 N, kutija počinje kliziti.' },
      misconception: { en: 'Pupils often think friction is always at its maximum value. If friction were 10 N against a 3 N push, the box would accelerate backward toward you, which is absurd.',
                       hr: 'Učenici često misle da je trenje uvijek najveće moguće. Da je trenje 10 N nasuprot guranju od 3 N, kutija bi ubrzavala natrag prema tebi, što je besmisleno.' } },

    { id: 'push-equals-friction', topic: 'forces', type: 'mc', level: 2,
      q: { en: 'You push a book across a table so that it slides at a constant speed. Compare your push F and the friction force Ftr.',
           hr: 'Guraš knjigu po stolu tako da klizi stalnom brzinom. Usporedi svoju silu F i silu trenja Ftr.' },
      options: [ { en: 'F > Ftr, otherwise the book would stop', hr: 'F > Ftr, inače bi se knjiga zaustavila' }, { en: 'F = Ftr', hr: 'F = Ftr' }, { en: 'F < Ftr', hr: 'F < Ftr' }, { en: 'Ftr = 0, because the book is already moving', hr: 'Ftr = 0, jer se knjiga već giba' } ],
      answer: 1,
      explain: { en: 'Constant speed means zero net force, so push and friction are equal. A bigger push would make the book speed up. The book stops when you let go because then only friction acts on it.',
                 hr: 'Stalna brzina znači da je rezultanta nula, pa su guranje i trenje jednaki. Veća sila ubrzavala bi knjigu. Knjiga se zaustavi kad je pustiš jer tada na nju djeluje samo trenje.' },
      misconception: { en: 'The idea "motion needs a winning force" comes from everyday life, where friction is always present. Steady motion needs balanced forces, not a bigger push.',
                       hr: 'Ideja da "gibanje treba jaču silu" dolazi iz svakodnevice, gdje trenje uvijek postoji. Jednoliko gibanje traži uravnotežene sile, a ne jače guranje.' } },

    { id: 'frictionless-cart-steady-push', topic: 'forces', type: 'mc', level: 2,
      q: { en: 'A cart on a perfectly smooth track (no friction, no air) is pushed with a steady force of 5 N for a long time. What happens?',
           hr: 'Kolica na savršeno glatkoj stazi (bez trenja, bez zraka) dugo guramo stalnom silom 5 N. Što se događa?' },
      options: [ { en: 'They move at a steady speed that depends on the force', hr: 'Gibaju se stalnom brzinom koja ovisi o sili' }, { en: 'They speed up at first, then move at a steady speed', hr: 'Najprije ubrzavaju, a zatim se gibaju stalnom brzinom' }, { en: 'They keep speeding up as long as the force acts', hr: 'Ubrzavaju sve dok sila djeluje' }, { en: 'They move a bit and stop when the force "runs out"', hr: 'Malo se pomaknu i stanu kad se sila "potroši"' } ],
      answer: 2,
      explain: { en: 'A net force always changes the speed: F = m · a, so a steady 5 N gives a steady acceleration and the speed grows and grows. A steady speed needs zero net force, not a steady push.',
                 hr: 'Rezultantna sila uvijek mijenja brzinu: F = m · a, pa stalnih 5 N daje stalno ubrzanje i brzina sve više raste. Stalna brzina traži rezultantu nula, a ne stalno guranje.' },
      misconception: { en: 'In everyday life a steady push gives a steady speed only because friction balances it. Without friction, the push itself is the net force.',
                       hr: 'U svakodnevici stalno guranje daje stalnu brzinu samo zato što ga trenje uravnotežuje. Bez trenja sama sila guranja je rezultanta.' } },

    { id: 'falling-balloon-acceleration', topic: 'forces', type: 'num', level: 3,
      q: { en: 'A balloon with a mass of 90 kg is falling. Air drag of 300 N and buoyancy of 60 N act upward on it. Find its acceleration. Use g = 10 N/kg.',
           hr: 'Balon mase 90 kg pada. Prema gore na njega djeluju otpor zraka 300 N i uzgon 60 N. Izračunaj ubrzanje balona. Uzmi g = 10 N/kg.' },
      answer: 6, min: 5.9, max: 6.1, unit: 'm/s²',
      explain: { en: 'Weight: G = 90 kg · 10 N/kg = 900 N downward. Upward forces: 300 N + 60 N = 360 N. Net force: 900 N − 360 N = 540 N downward. a = F / m = 540 N / 90 kg = 6 m/s².',
                 hr: 'Težina: G = 90 kg · 10 N/kg = 900 N prema dolje. Sile prema gore: 300 N + 60 N = 360 N. Rezultanta: 900 N − 360 N = 540 N prema dolje. a = F / m = 540 N / 90 kg = 6 m/s².' } },

    /* ---------- GRAVITY / GRAVITACIJA ---------- */
    { id: 'earth-apple-equal-forces', topic: 'gravity', type: 'mc', level: 2,
      q: { en: 'Earth pulls a falling apple with a force of 1 N. With what force does the apple pull Earth?',
           hr: 'Zemlja privlači jabuku koja pada silom 1 N. Kolikom silom jabuka privlači Zemlju?' },
      options: [ { en: '0 N, the apple is far too small', hr: '0 N, jabuka je premala' }, { en: 'much less than 1 N', hr: 'mnogo manjom od 1 N' }, { en: 'exactly 1 N', hr: 'točno 1 N' }, { en: 'more than 1 N, because Earth is huge', hr: 'većom od 1 N, jer je Zemlja golema' } ],
      answer: 2,
      explain: { en: 'Gravity is a mutual attraction: the two forces are equal (Newton\'s third law). The effects differ enormously because of the masses: the same 1 N gives the apple an acceleration of about 10 m/s² and Earth an acceleration far too small to measure.',
                 hr: 'Gravitacija je uzajamno privlačenje: dvije sile su jednake (treći Newtonov zakon). Učinci se silno razlikuju zbog masa: ista sila od 1 N jabuci daje ubrzanje oko 10 m/s², a Zemlji ubrzanje premaleno da bi se izmjerilo.' },
      misconception: { en: 'Pupils believe the bigger body pulls harder. The force is the same; what differs is how much each body accelerates.',
                       hr: 'Učenici vjeruju da veće tijelo privlači jače. Sila je ista; razlikuje se samo koliko svako tijelo ubrzava.' } },

    { id: 'two-balls-fall-no-air', topic: 'gravity', type: 'mc', level: 1,
      q: { en: 'A 1 kg ball and a 5 kg ball are dropped at the same moment from the same height in a room with no air. What happens?',
           hr: 'Kuglu mase 1 kg i kuglu mase 5 kg istodobno pustimo s iste visine u prostoriji bez zraka. Što se događa?' },
      options: [ { en: 'The 5 kg ball lands first and is faster', hr: 'Kugla od 5 kg pada prva i brža je' }, { en: 'The 1 kg ball lands first', hr: 'Kugla od 1 kg pada prva' }, { en: 'They land at the same time with the same speed', hr: 'Padnu istodobno i jednakom brzinom' }, { en: 'They land at the same time, but the heavier one is faster', hr: 'Padnu istodobno, ali teža je brža' } ],
      answer: 2,
      explain: { en: 'Gravity pulls the heavier ball five times harder, but it also has five times more mass to accelerate, so both gain speed at the same rate (about 10 m/s every second) and arrive together with the same speed. Only air resistance makes a feather fall more slowly than a stone.',
                 hr: 'Sila teža težu kuglu vuče pet puta jače, ali ona ima i pet puta veću masu koju treba ubrzati, pa obje dobivaju brzinu jednako brzo (oko 10 m/s svake sekunde) i stižu istodobno jednakom brzinom. Samo otpor zraka čini da pero pada sporije od kamena.' },
      misconception: { en: '"Heavier falls faster" is one of the oldest misconceptions, held since Aristotle. Galileo\'s reasoning and the hammer-and-feather drop on the Moon show it is wrong without air.',
                       hr: '"Teže pada brže" jedna je od najstarijih zabluda, još od Aristotela. Galileovo razmišljanje i pokus s čekićem i perom na Mjesecu pokazuju da bez zraka to nije točno.' } },

    { id: 'mass-weight-moon', topic: 'gravity', type: 'mc', level: 1,
      q: { en: 'An astronaut has a mass of 80 kg on Earth (g = 10 N/kg). On the Moon gravity is about 6 times weaker. What are her mass and weight on the Moon?',
           hr: 'Astronautkinja na Zemlji ima masu 80 kg (g = 10 N/kg). Na Mjesecu je sila teža oko 6 puta slabija. Kolika je njezina masa i težina na Mjesecu?' },
      options: [ { en: 'mass 80 kg, weight about 130 N', hr: 'masa 80 kg, težina oko 130 N' }, { en: 'mass about 13 kg, weight 800 N', hr: 'masa oko 13 kg, težina 800 N' }, { en: 'mass about 13 kg, weight about 130 N', hr: 'masa oko 13 kg, težina oko 130 N' }, { en: 'mass 80 kg, weight 800 N', hr: 'masa 80 kg, težina 800 N' } ],
      answer: 0,
      explain: { en: 'Mass is the amount of matter and does not change with location. Weight is the force of gravity: 800 N on Earth, about 800 N / 6 ≈ 130 N on the Moon.',
                 hr: 'Masa je količina tvari i ne mijenja se s mjestom. Težina je sila teža: 800 N na Zemlji, a na Mjesecu oko 800 N / 6 ≈ 130 N.' },
      misconception: { en: 'In everyday speech "weight" is used for mass (kilograms), so pupils expect both to shrink on the Moon. Only the force does.',
                       hr: 'U svakodnevnom govoru "težina" se koristi za masu (kilograme), pa učenici očekuju da se na Mjesecu smanjuje oboje. Smanjuje se samo sila.' } },

    { id: 'rank-pendulum-periods', topic: 'gravity', type: 'rank', level: 2,
      q: { en: 'Four pendulums swing with small swings. Rank them from the longest period (slowest swing) to the shortest.',
           hr: 'Četiri njihala titraju s malim otklonima. Poredaj ih od najduljeg perioda (najsporijeg titranja) do najkraćeg.' },
      items: [ { en: 'a 2 m string with a 50 g washer', hr: 'nit od 2 m s podloškom od 50 g' }, { en: 'a 1 m string with a 200 g washer', hr: 'nit od 1 m s podloškom od 200 g' }, { en: 'a 50 cm string with a 100 g washer', hr: 'nit od 50 cm s podloškom od 100 g' }, { en: 'a 25 cm string with a 500 g washer', hr: 'nit od 25 cm s podloškom od 500 g' } ],
      explain: { en: 'The period depends only on the length (and on g), not on the mass: a longer string, a slower swing. Four times the length gives twice the period, so the 2 m pendulum swings twice as slowly as the 50 cm one.',
                 hr: 'Period ovisi samo o duljini (i o g), a ne o masi: dulja nit, sporije titranje. Četiri puta veća duljina daje dvostruko dulji period, pa njihalo od 2 m titra dvostruko sporije od onoga od 50 cm.' } },

    /* ---------- MOTION / GIBANJE ---------- */
    { id: 'string-cut-tangent', topic: 'motion', type: 'mc', level: 2,
      q: { en: 'A ball on a string is whirled in a horizontal circle. Suddenly the string is cut. Seen from above, how does the ball move right after?',
           hr: 'Kuglicu na niti vrtimo u vodoravnoj kružnici. Nit iznenada puknemo. Gledano odozgo, kako se kuglica giba odmah nakon toga?' },
      options: [ { en: 'straight ahead, along the tangent', hr: 'ravno naprijed, po tangenti' }, { en: 'curving outward in a spiral', hr: 'zakrivljeno prema van, spiralno' }, { en: 'it keeps going in the circle for a while', hr: 'još se neko vrijeme giba po kružnici' }, { en: 'straight outward, away from the centre', hr: 'ravno prema van, od središta' } ],
      answer: 0,
      explain: { en: 'The string provided the force that kept bending the path toward the centre. With no force, Newton\'s first law says the ball keeps its velocity: straight, at the speed it had, in the direction it was moving at that moment, which is the tangent.',
                 hr: 'Nit je davala silu koja je stalno zakretala putanju prema središtu. Bez sile, prema prvom Newtonovom zakonu, kuglica zadržava brzinu: ravno, brzinom koju je imala, u smjeru u kojem se u tom trenutku gibala, a to je tangenta.' },
      misconception: { en: 'Many draw a spiral or a straight line radially outward, imagining a "centrifugal force" that throws the ball out. Nothing pushes outward; the ball simply stops turning.',
                       hr: 'Mnogi crtaju spiralu ili ravnu crtu prema van, zamišljajući "centrifugalnu silu" koja izbacuje kuglicu. Ništa ne gura prema van; kuglica jednostavno prestaje skretati.' } },

    { id: 'radius-centripetal-force', topic: 'motion', type: 'mc', level: 3,
      q: { en: 'Two toy cars of equal mass drive at the same speed, one on a circle of radius 1 m, the other on a circle of radius 2 m. Which needs the bigger force toward the centre to stay on its circle?',
           hr: 'Dva autića jednake mase voze jednakom brzinom, jedan po kružnici polumjera 1 m, drugi po kružnici polumjera 2 m. Kojemu treba veća sila prema središtu da ostane na svojoj kružnici?' },
      options: [ { en: 'the one on the smaller circle (1 m)', hr: 'onomu na manjoj kružnici (1 m)' }, { en: 'the one on the bigger circle (2 m)', hr: 'onomu na većoj kružnici (2 m)' }, { en: 'the same force, same speed', hr: 'jednaka sila, jednaka brzina' }, { en: 'neither; a steady speed needs no force', hr: 'nijednomu; stalna brzina ne traži silu' } ],
      answer: 0,
      explain: { en: 'The force toward the centre is F = m · v² / r. At the same speed a tighter turn (smaller r) changes the direction faster and needs a bigger force. That is why sharp bends on roads have lower speed limits.',
                 hr: 'Sila prema središtu je F = m · v² / r. Pri jednakoj brzini oštriji zavoj (manji r) brže mijenja smjer i traži veću silu. Zato oštri zavoji na cestama imaju manja ograničenja brzine.' },
      misconception: { en: 'A common answer is "same speed, same force" or "no force because the speed is steady". Changing direction is also a change of velocity and needs a force.',
                       hr: 'Čest je odgovor "jednaka brzina, jednaka sila" ili "nema sile jer je brzina stalna". Promjena smjera također je promjena brzine kao vektora i traži silu.' } },

    { id: 'graph-steeper-faster', topic: 'motion', type: 'mc', level: 1,
      q: { en: 'On a distance-time (s-t) graph the line for cyclist A is steeper than the line for cyclist B. Both lines are straight. What does this tell you?',
           hr: 'Na grafu puta i vremena (s-t graf) pravac ciklista A strmiji je od pravca ciklista B. Oba su pravci. Što nam to govori?' },
      options: [ { en: 'A is riding uphill', hr: 'A vozi uzbrdo' }, { en: 'A is faster than B', hr: 'A je brži od B' }, { en: 'A is slower than B', hr: 'A je sporiji od B' }, { en: 'A started earlier', hr: 'A je krenuo ranije' } ],
      answer: 1,
      explain: { en: 'The slope of an s-t line is distance divided by time, that is speed. Steeper means more metres every second. A graph is not a picture of the road: "uphill" on the paper says nothing about hills.',
                 hr: 'Nagib pravca na s-t grafu je put podijeljen vremenom, dakle brzina. Strmiji pravac znači više metara svake sekunde. Graf nije slika ceste: "uzbrdo" na papiru ne govori ništa o brdima.' },
      misconception: { en: 'Pupils often read a graph as a picture of the motion ("the line goes up, so the bike goes uphill"). The axes are distance and time, not height and distance.',
                       hr: 'Učenici često čitaju graf kao sliku gibanja ("crta ide gore, pa bicikl ide uzbrdo"). Osi su put i vrijeme, a ne visina i udaljenost.' } },

    { id: 'helen-bike-average-speed', topic: 'motion', type: 'num', level: 2,
      q: { en: 'Helen rode her bike 4 km to the river in 9 minutes, then 3 km back home by a shorter road in 6 minutes. What was her average speed for the whole trip, in km/h?',
           hr: 'Helena se biciklom odvezla 4 km do rijeke za 9 minuta, a zatim se kraćim putem vratila 3 km kući za 6 minuta. Kolika je bila njezina prosječna brzina na cijelom putu, u km/h?' },
      answer: 28, min: 27, max: 29, unit: 'km/h',
      explain: { en: 'Average speed = total distance / total time = 7 km / 15 min = 7 km / 0.25 h = 28 km/h. You cannot simply average the two speeds (26.7 km/h and 30 km/h), because she spent different times at them.',
                 hr: 'Prosječna brzina = ukupni put / ukupno vrijeme = 7 km / 15 min = 7 km / 0,25 h = 28 km/h. Ne možeš jednostavno uzeti sredinu dviju brzina (26,7 km/h i 30 km/h), jer je njima vozila različito dugo.' } },

    /* ---------- ENERGY / ENERGIJA ---------- */
    { id: 'potential-energy-zero-level', topic: 'energy', type: 'mc', level: 2,
      q: { en: 'A 1 kg book lies on a shelf 2 m above the floor of a room on the third floor. Which statement about its gravitational potential energy is true? (g = 10 N/kg)',
           hr: 'Knjiga mase 1 kg leži na polici 2 m iznad poda sobe na trećem katu. Koja je tvrdnja o njezinoj gravitacijskoj potencijalnoj energiji točna? (g = 10 N/kg)' },
      options: [ { en: 'It is exactly 20 J; there is only one correct value.', hr: 'Iznosi točno 20 J; postoji samo jedna točna vrijednost.' }, { en: 'It depends on the zero level we choose; only the change ΔEp has physical meaning.', hr: 'Ovisi o nultoj razini koju odaberemo; fizikalni smisao ima samo promjena ΔEp.' }, { en: 'It is zero, because the book is not moving.', hr: 'Iznosi nula, jer se knjiga ne giba.' }, { en: 'It is the same as its kinetic energy.', hr: 'Jednaka je njezinoj kinetičkoj energiji.' } ],
      answer: 1,
      explain: { en: 'Ep = m · g · h needs a height h, and height is measured from a level we choose: the floor, the ground outside, sea level. Different choices give different numbers, but the change when the book falls 2 m to the floor is always 20 J. Nature only cares about changes.',
                 hr: 'Ep = m · g · h traži visinu h, a visinu mjerimo od razine koju sami odaberemo: pod, tlo ispred zgrade, razina mora. Različiti izbori daju različite brojeve, ali promjena kad knjiga padne 2 m na pod uvijek je 20 J. Prirodi su važne samo promjene.' },
      misconception: { en: 'Pupils think potential energy is a fixed property of the body, like mass. It is a relation between the body and a chosen reference level.',
                       hr: 'Učenici misle da je potencijalna energija stalno svojstvo tijela, kao masa. Ona je odnos između tijela i odabrane referentne razine.' } },

    { id: 'suitcase-horizontal-zero-work', topic: 'energy', type: 'mc', level: 2,
      q: { en: 'You carry a 10 kg suitcase 50 m along a flat corridor at a steady speed, holding it still beside you. How much work (in the physics sense) do you do on the suitcase? (g = 10 N/kg)',
           hr: 'Nosiš kovčeg mase 10 kg 50 m ravnim hodnikom stalnom brzinom, držeći ga mirno uz sebe. Koliki rad (u fizikalnom smislu) obavljaš na kovčegu? (g = 10 N/kg)' },
      options: [ { en: '5000 J', hr: '5000 J' }, { en: '500 J', hr: '500 J' }, { en: 'zero', hr: 'nula' }, { en: 'it cannot be known without the time', hr: 'ne može se znati bez vremena' } ],
      answer: 2,
      explain: { en: 'Work = force × distance in the direction of the force. Your hand pulls up with 100 N, but the suitcase moves horizontally, perpendicular to that force, and neither its speed nor its height changes. The work on the suitcase is zero, even though your arm gets tired.',
                 hr: 'Rad = sila × put u smjeru sile. Tvoja ruka vuče prema gore silom 100 N, ali kovčeg se giba vodoravno, okomito na tu silu, i ne mijenjaju se ni njegova brzina ni visina. Rad na kovčegu je nula, iako se tvoja ruka umori.' },
      misconception: { en: 'Everyday "effort" and physics "work" are different words. Being tired does not mean energy was transferred to the suitcase.',
                       hr: 'Svakodnevni "trud" i fizikalni "rad" različite su riječi. Umor ne znači da je kovčegu predana energija.' } },

    { id: 'rank-kinetic-energy', topic: 'energy', type: 'rank', level: 2,
      q: { en: 'Rank these from the largest kinetic energy to the smallest.', hr: 'Poredaj od najveće kinetičke energije do najmanje.' },
      items: [ { en: 'a 1000 kg car at 20 m/s', hr: 'automobil mase 1000 kg brzinom 20 m/s' }, { en: 'a 60 kg runner at 10 m/s', hr: 'trkač mase 60 kg brzinom 10 m/s' }, { en: 'a 2 kg ball at 30 m/s', hr: 'lopta mase 2 kg brzinom 30 m/s' }, { en: 'a 100 kg scooter rider at 3 m/s', hr: 'vozač romobila mase 100 kg brzinom 3 m/s' } ],
      explain: { en: 'Ek = m · v² / 2. Speed counts squared: the ball is light but fast, so it beats the heavy, slow scooter rider. Car: 200 000 J; runner: 3000 J; ball: 900 J; scooter rider: 450 J.',
                 hr: 'Ek = m · v² / 2. Brzina se računa na kvadrat: lopta je lagana, ali brza, pa pobjeđuje teškog, sporog vozača romobila. Automobil: 200 000 J; trkač: 3000 J; lopta: 900 J; vozač romobila: 450 J.' } },

    { id: 'estimate-stairs-power', topic: 'energy', type: 'num', level: 3,
      q: { en: 'Estimate the power of a 50 kg pupil who runs up a staircase 3 m high in 5 s. Use g = 10 N/kg.',
           hr: 'Procijeni snagu učenika mase 50 kg koji za 5 s istrči stubište visoko 3 m. Uzmi g = 10 N/kg.' },
      answer: 300, min: 250, max: 350, unit: 'W',
      explain: { en: 'Work against gravity: W = m · g · h = 50 kg · 10 N/kg · 3 m = 1500 J. Power: P = W / t = 1500 J / 5 s = 300 W, about three old-style light bulbs. A top athlete can keep up over 1000 W for a few seconds.',
                 hr: 'Rad protiv sile teže: W = m · g · h = 50 kg · 10 N/kg · 3 m = 1500 J. Snaga: P = W / t = 1500 J / 5 s = 300 W, otprilike tri stare žarulje. Vrhunski sportaš može nekoliko sekundi držati više od 1000 W.' } },

    /* ---------- HEAT / TOPLINA ---------- */
    { id: 'sweater-no-heat', topic: 'heat', type: 'mc', level: 1,
      q: { en: 'You put on a wool sweater and soon feel warm. Where does the warmth come from?',
           hr: 'Obučeš vuneni pulover i ubrzo ti je toplo. Odakle dolazi toplina?' },
      options: [ { en: 'The sweater produces heat', hr: 'Pulover proizvodi toplinu' }, { en: 'The sweater is warm inside', hr: 'Pulover je iznutra topao' }, { en: 'The sweater slows down the loss of the heat your body produces', hr: 'Pulover usporava gubitak topline koju proizvodi tvoje tijelo' }, { en: 'The wool rubs the skin and heats it', hr: 'Vuna trlja kožu i grije je' } ],
      answer: 2,
      explain: { en: 'A sweater is a thermal insulator: air trapped in the wool slows the flow of heat from your body to the cold air. The source of the heat is your body (about 100 W at rest). A thermometer wrapped in a sweater in a cold room does not warm up at all.',
                 hr: 'Pulover je toplinski izolator: zrak zarobljen u vuni usporava prijelaz topline s tvojeg tijela na hladan zrak. Izvor topline je tvoje tijelo (oko 100 W u mirovanju). Termometar umotan u pulover u hladnoj sobi uopće se ne ugrije.' },
      misconception: { en: 'Children often think clothes are "warm things". Try it: a sweater left in a cold room is exactly as cold as the room.',
                       hr: 'Djeca često misle da je odjeća "topla stvar". Provjeri: pulover ostavljen u hladnoj sobi hladan je točno koliko i soba.' } },

    { id: 'estimate-heater-kwh', topic: 'heat', type: 'num', level: 2,
      q: { en: 'An electric heater of power 2 kW warms a classroom for the whole school day, 6 hours. How much energy does it convert into heat, in kWh?',
           hr: 'Električna grijalica snage 2 kW grije učionicu cijeli školski dan, 6 sati. Koliko energije pretvori u toplinu, u kWh?' },
      answer: 12, min: 11, max: 13, unit: 'kWh',
      explain: { en: 'Energy = power × time = 2 kW × 6 h = 12 kWh. One kilowatt-hour is the energy a 1 kW device uses in one hour, so 12 kWh is about 12 × 3.6 MJ ≈ 43 MJ.',
                 hr: 'Energija = snaga × vrijeme = 2 kW × 6 h = 12 kWh. Jedan kilovatsat je energija koju uređaj snage 1 kW potroši za jedan sat, pa je 12 kWh oko 12 × 3,6 MJ ≈ 43 MJ.' } },

    /* ---------- DENSITY / GUSTOĆA ---------- */
    { id: 'rank-density-materials', topic: 'density', type: 'rank', level: 1,
      q: { en: 'Rank these materials from the largest density to the smallest.', hr: 'Poredaj ove tvari od najveće gustoće do najmanje.' },
      items: [ { en: 'iron', hr: 'željezo' }, { en: 'aluminium', hr: 'aluminij' }, { en: 'water', hr: 'voda' }, { en: 'ice', hr: 'led' }, { en: 'cork', hr: 'pluto' } ],
      explain: { en: 'Density = mass / volume, how much mass fits into one cubic metre. Iron about 7900 kg/m³, aluminium 2700 kg/m³, water 1000 kg/m³, ice about 920 kg/m³ (which is why it floats on water), cork about 240 kg/m³.',
                 hr: 'Gustoća = masa / obujam, koliko mase stane u jedan kubični metar. Željezo oko 7900 kg/m³, aluminij 2700 kg/m³, voda 1000 kg/m³, led oko 920 kg/m³ (zato pluta na vodi), pluto oko 240 kg/m³.' } },

    { id: 'estimate-air-mass-classroom', topic: 'density', type: 'num', level: 2,
      q: { en: 'Estimate the mass of the air in a classroom 8 m long, 6 m wide and 3 m high. The density of air is about 1.2 kg/m³.',
           hr: 'Procijeni masu zraka u učionici dugoj 8 m, širokoj 6 m i visokoj 3 m. Gustoća zraka je oko 1,2 kg/m³.' },
      answer: 173, min: 150, max: 200, unit: 'kg',
      explain: { en: 'Volume: V = 8 m · 6 m · 3 m = 144 m³. Mass: m = ρ · V = 1.2 kg/m³ · 144 m³ ≈ 173 kg, about the mass of two adults. Air is not "nothing".',
                 hr: 'Obujam: V = 8 m · 6 m · 3 m = 144 m³. Masa: m = ρ · V = 1,2 kg/m³ · 144 m³ ≈ 173 kg, otprilike masa dviju odraslih osoba. Zrak nije "ništa".' } },

    /* ---------- MATTER / TVAR ---------- */
    { id: 'ice-floats-density', topic: 'matter', type: 'mc', level: 1,
      q: { en: 'Ice cubes float in a glass of water. Why?', hr: 'Kockice leda plutaju u čaši vode. Zašto?' },
      options: [ { en: 'Ice is lighter than water', hr: 'Led je lakši od vode' }, { en: 'Ice is less dense than water, because water expands when it freezes', hr: 'Led ima manju gustoću od vode, jer se voda pri smrzavanju širi' }, { en: 'Ice is cold, and cold things rise', hr: 'Led je hladan, a hladne stvari se dižu' }, { en: 'Air bubbles in the ice hold it up', hr: 'Mjehurići zraka u ledu drže ga na površini' } ],
      answer: 1,
      explain: { en: 'When water freezes, its molecules lock into an open pattern that takes up about 9 % more space, so ice has a lower density (about 920 kg/m³) than liquid water (1000 kg/m³). A less dense body floats in a denser liquid. That is why pipes burst in winter and lakes freeze from the top.',
                 hr: 'Kad se voda smrzava, njezine se molekule slažu u rahli raspored koji zauzima oko 9 % više prostora, pa led ima manju gustoću (oko 920 kg/m³) od tekuće vode (1000 kg/m³). Tijelo manje gustoće pluta u tekućini veće gustoće. Zato zimi pucaju cijevi i jezera se smrzavaju od površine.' },
      misconception: { en: '"Lighter" is not the point: an iceberg is far heavier than a glass of water, yet it floats. What matters is mass per volume, the density.',
                       hr: '"Lakši" nije bit: ledeni brijeg daleko je teži od čaše vode, a ipak pluta. Važna je masa po obujmu, dakle gustoća.' } },

    { id: 'heated-particles-do-not-grow', topic: 'matter', type: 'mc', level: 2,
      q: { en: 'A metal ball is heated and expands. What happens to its atoms?', hr: 'Metalnu kuglu zagrijemo i ona se raširi. Što se događa s njezinim atomima?' },
      options: [ { en: 'Each atom gets bigger', hr: 'Svaki atom postaje veći' }, { en: 'The atoms vibrate more and sit slightly farther apart', hr: 'Atomi jače titraju i malo se razmaknu' }, { en: 'New atoms are created', hr: 'Nastaju novi atomi' }, { en: 'The atoms melt', hr: 'Atomi se tope' } ],
      answer: 1,
      explain: { en: 'Atoms do not change size. Heating makes them vibrate more vigorously, so on average they sit a little farther apart and the whole ball grows. The number of atoms and their size stay the same.',
                 hr: 'Atomi ne mijenjaju veličinu. Zagrijavanjem jače titraju, pa su u prosjeku malo udaljeniji jedan od drugoga i cijela kugla raste. Broj atoma i njihova veličina ostaju isti.' },
      misconception: { en: 'Pupils often give the particles the properties of the whole object: particles that "expand", "melt" or "get hot". Temperature is about how fast particles move, not about their size.',
                       hr: 'Učenici često česticama pripisuju svojstva cijelog tijela: čestice koje se "šire", "tope" ili "ugriju". Temperatura govori o tome kako se brzo čestice gibaju, a ne o njihovoj veličini.' } },

    /* ---------- PRESSURE / TLAK ---------- */
    { id: 'rank-pressure-shoes', topic: 'pressure', type: 'rank', level: 2,
      q: { en: 'Rank from the largest pressure on the floor to the smallest.', hr: 'Poredaj od najvećeg tlaka na pod do najmanjeg.' },
      items: [ { en: 'a woman of 600 N standing on one high heel (1 cm²)', hr: 'žena težine 600 N na jednoj visokoj peti (1 cm²)' }, { en: 'a man of 800 N standing on one foot (200 cm²)', hr: 'muškarac težine 800 N na jednoj nozi (200 cm²)' }, { en: 'a child of 300 N standing on two feet (300 cm²)', hr: 'dijete težine 300 N na obje noge (300 cm²)' }, { en: 'a skier of 700 N on two skis (3500 cm²)', hr: 'skijaš težine 700 N na dvjema skijama (3500 cm²)' } ],
      explain: { en: 'p = F / A: pressure is force per area. The heel has a tiny area, so 600 N / 1 cm² gives a huge 600 N/cm². The man on one foot: 800 N / 200 cm² = 4 N/cm²; the child: 300 N / 300 cm² = 1 N/cm²; the skier spreads 700 N over 3500 cm², only 0.2 N/cm², which is why skis do not sink into snow.',
                 hr: 'p = F / A: tlak je sila po površini. Peta ima sićušnu površinu, pa 600 N / 1 cm² daje golemih 600 N/cm². Muškarac na jednoj nozi: 800 N / 200 cm² = 4 N/cm²; dijete: 300 N / 300 cm² = 1 N/cm²; skijaš raspodijeli 700 N na 3500 cm², samo 0,2 N/cm², zato skije ne propadaju u snijeg.' } },

    { id: 'estimate-pupil-pressure', topic: 'pressure', type: 'num', level: 2,
      q: { en: 'A pupil of mass 50 kg stands on both feet. Each sole has an area of about 200 cm². Estimate the pressure on the floor in kPa. Use g = 10 N/kg.',
           hr: 'Učenik mase 50 kg stoji na obje noge. Svaki potplat ima površinu oko 200 cm². Procijeni tlak na pod u kPa. Uzmi g = 10 N/kg.' },
      answer: 12.5, min: 10, max: 15, unit: 'kPa',
      explain: { en: 'Weight: 500 N. Area: 2 · 200 cm² = 400 cm² = 0.04 m². p = F / A = 500 N / 0.04 m² = 12 500 Pa = 12.5 kPa, about an eighth of atmospheric pressure (100 kPa).',
                 hr: 'Težina: 500 N. Površina: 2 · 200 cm² = 400 cm² = 0,04 m². p = F / A = 500 N / 0,04 m² = 12 500 Pa = 12,5 kPa, oko osmine atmosferskog tlaka (100 kPa).' } },

    /* ---------- LEVERS / POLUGE ---------- */
    { id: 'lever-does-not-save-work', topic: 'levers', type: 'mc', level: 2,
      q: { en: 'With a long crowbar you lift a 600 N rock using only 100 N. Does the lever save work?',
           hr: 'Dugom polugom podižeš kamen težine 600 N silom od samo 100 N. Štedi li poluga rad?' },
      options: [ { en: 'Yes, you do 6 times less work', hr: 'Da, obavljaš 6 puta manji rad' }, { en: 'No: you push with 6 times less force but over a 6 times longer distance, so the work is the same', hr: 'Ne: guraš 6 puta manjom silom, ali na 6 puta duljem putu, pa je rad jednak' }, { en: 'Yes, the lever adds energy', hr: 'Da, poluga dodaje energiju' }, { en: 'No, the lever doubles the work', hr: 'Ne, poluga udvostručuje rad' } ],
      answer: 1,
      explain: { en: 'A lever trades force for distance: to lift the rock 10 cm your hand moves 60 cm. Work = force × distance: 100 N · 0.6 m = 60 J, the same as 600 N · 0.1 m = 60 J. No simple machine saves work; it only makes the job comfortable.',
                 hr: 'Poluga mijenja silu za put: da kamen podigneš 10 cm, tvoja ruka prijeđe 60 cm. Rad = sila × put: 100 N · 0,6 m = 60 J, isto kao 600 N · 0,1 m = 60 J. Nijedan jednostavni stroj ne štedi rad; samo olakšava posao.' },
      misconception: { en: '"Less force" feels like "less work". In physics work needs both force and distance, and the lever makes you move farther.',
                       hr: '"Manja sila" osjeća se kao "manji rad". U fizici rad traži i silu i put, a poluga te tjera da prijeđeš dulji put.' } },

    { id: 'seesaw-balance', topic: 'levers', type: 'mc', level: 1,
      q: { en: 'A 30 kg child sits 2 m from the pivot of a seesaw. Where should a 60 kg parent sit on the other side to balance it?',
           hr: 'Dijete mase 30 kg sjedi 2 m od osi klackalice. Gdje na drugoj strani treba sjesti roditelj mase 60 kg da bi klackalica bila u ravnoteži?' },
      options: [ { en: '4 m from the pivot', hr: '4 m od osi' }, { en: '2 m from the pivot', hr: '2 m od osi' }, { en: '1 m from the pivot', hr: '1 m od osi' }, { en: 'It cannot balance; the parent is heavier', hr: 'Ne može biti u ravnoteži; roditelj je teži' } ],
      answer: 2,
      explain: { en: 'A lever balances when force × arm is equal on both sides: 300 N · 2 m = 600 N · x, so x = 1 m. Twice the weight needs half the arm.',
                 hr: 'Poluga je u ravnoteži kad je umnožak sile i kraka jednak na obje strane: 300 N · 2 m = 600 N · x, pa je x = 1 m. Dvostruko veća težina traži dvostruko kraći krak.' },
      misconception: { en: 'Pupils often think the heavier person always wins. The arm (distance from the pivot) matters just as much as the force.',
                       hr: 'Učenici često misle da teža osoba uvijek pobjeđuje. Krak (udaljenost od osi) jednako je važan kao i sila.' } },

    /* ---------- ELECTRICITY / ELEKTRICITET ---------- */
    { id: 'ammeters-before-after-bulb', topic: 'electricity', type: 'mc', level: 2,
      q: { en: 'In a simple circuit with one bulb, one ammeter is placed before the bulb and another after it. What do they read?',
           hr: 'U jednostavnom strujnom krugu s jednom žaruljom jedan je ampermetar spojen ispred žarulje, a drugi iza nje. Što pokazuju?' },
      options: [ { en: 'The first reads more; the bulb uses up some of the current', hr: 'Prvi pokazuje više; žarulja potroši dio struje' }, { en: 'The second reads more', hr: 'Drugi pokazuje više' }, { en: 'Both read the same current', hr: 'Oba pokazuju jednaku struju' }, { en: 'The second reads zero', hr: 'Drugi pokazuje nulu' } ],
      answer: 2,
      explain: { en: 'Current is a flow of charge, like water in a closed loop of pipes: what flows into the bulb flows out of it. The bulb uses energy, not charge; the charges give energy to the bulb and move on. Both ammeters show the same current.',
                 hr: 'Struja je tok naboja, kao voda u zatvorenom krugu cijevi: što uteče u žarulju, iz nje i isteče. Žarulja troši energiju, a ne naboj; naboji predaju energiju žarulji i nastavljaju dalje. Oba ampermetra pokazuju jednaku struju.' },
      misconception: { en: 'The "current gets used up" idea is one of the most common. Electrons are not consumed; the battery\'s energy is.',
                       hr: 'Ideja da se "struja troši" jedna je od najčešćih. Elektroni se ne troše; troši se energija baterije.' } },

    { id: 'rank-bulb-brightness', topic: 'electricity', type: 'rank', level: 3,
      q: { en: 'Identical bulbs and identical batteries. Rank the described bulb from the brightest to the dimmest.',
           hr: 'Jednake žarulje i jednake baterije. Poredaj opisanu žarulju od najsjajnije do najslabije.' },
      items: [ { en: 'a single bulb on two batteries connected in series', hr: 'jedna žarulja na dvije baterije spojene serijski' }, { en: 'one of two bulbs connected in parallel to one battery', hr: 'jedna od dviju žarulja spojenih paralelno na jednu bateriju' }, { en: 'one of two bulbs connected in series to one battery', hr: 'jedna od dviju žarulja spojenih serijski na jednu bateriju' }, { en: 'one of three bulbs connected in series to one battery', hr: 'jedna od triju žarulja spojenih serijski na jednu bateriju' } ],
      explain: { en: 'In parallel every bulb gets the full battery voltage and shines as if it were alone. In series the bulbs share the voltage: two bulbs get half each, three get a third each, so they are much dimmer. Two batteries in series double the voltage, so a single bulb shines brighter (and may burn out).',
                 hr: 'U paralelnom spoju svaka žarulja dobiva puni napon baterije i svijetli kao da je sama. U serijskom spoju žarulje dijele napon: dvije dobiju po polovicu, tri po trećinu, pa svijetle mnogo slabije. Dvije baterije u seriji udvostručuju napon, pa jedna žarulja svijetli jače (i može pregorjeti).' } },

    /* ---------- MAGNETISM / MAGNETIZAM ---------- */
    { id: 'magnet-not-all-metals', topic: 'magnetism', type: 'mc', level: 1,
      q: { en: 'Which of these does a magnet attract?', hr: 'Što od navedenoga magnet privlači?' },
      options: [ { en: 'every metal object', hr: 'svaki metalni predmet' }, { en: 'a copper wire and an aluminium can', hr: 'bakrenu žicu i aluminijsku limenku' }, { en: 'an iron nail, but not a copper wire', hr: 'željezni čavao, ali ne bakrenu žicu' }, { en: 'only other magnets', hr: 'samo druge magnete' } ],
      answer: 2,
      explain: { en: 'Magnets strongly attract only a few metals: iron, nickel, cobalt and their alloys such as steel. Copper, aluminium, gold and silver are metals that a magnet does not noticeably pull. That is why a fridge magnet does not stick to an aluminium pot.',
                 hr: 'Magnet jako privlači samo nekoliko metala: željezo, nikal, kobalt i njihove legure poput čelika. Bakar, aluminij, zlato i srebro metali su koje magnet zamjetno ne privlači. Zato magnet s hladnjaka ne prianja na aluminijsku posudu.' },
      misconception: { en: '"Metal" and "magnetic" are not the same thing. Test it with an aluminium can (not attracted) and a steel paper clip (attracted).',
                       hr: '"Metalno" i "magnetično" nisu isto. Provjeri s aluminijskom limenkom (ne privlači se) i čeličnom spajalicom (privlači se).' } },

    { id: 'cut-magnet-two-poles', topic: 'magnetism', type: 'mc', level: 2,
      q: { en: 'You cut a bar magnet in half, between its north and south poles. What do you get?',
           hr: 'Štapićasti magnet prerežeš na pola, između sjevernog i južnog pola. Što dobiješ?' },
      options: [ { en: 'one piece that is only north and one that is only south', hr: 'jedan komad koji je samo sjeverni i jedan koji je samo južni pol' }, { en: 'two smaller magnets, each with a north and a south pole', hr: 'dva manja magneta, svaki sa sjevernim i južnim polom' }, { en: 'two pieces that are no longer magnets', hr: 'dva komada koji više nisu magneti' }, { en: 'one piece with both poles and one with none', hr: 'jedan komad s oba pola i jedan bez polova' } ],
      answer: 1,
      explain: { en: 'A magnet is made of countless tiny magnetic regions, each with its own north and south. Cutting simply makes two shorter magnets. No one has ever isolated a single magnetic pole.',
                 hr: 'Magnet se sastoji od bezbroj sićušnih magnetskih područja, svako sa svojim sjevernim i južnim polom. Rezanjem jednostavno nastaju dva kraća magneta. Nitko nikad nije izdvojio jedan jedini magnetski pol.' },
      misconception: { en: 'Pupils imagine the poles as "stuff" stored at the two ends. Magnetism is a property of the whole material.',
                       hr: 'Učenici zamišljaju polove kao "tvar" spremljenu na dvama krajevima. Magnetizam je svojstvo cijelog materijala.' } },

    /* ---------- WAVES / VALOVI ---------- */
    { id: 'sound-needs-medium', topic: 'waves', type: 'mc', level: 1,
      q: { en: 'In space films a spaceship explodes with a loud bang. Could an astronaut nearby hear it through the vacuum of space?',
           hr: 'U svemirskim filmovima svemirski brod eksplodira uz glasan prasak. Bi li astronaut u blizini to mogao čuti kroz vakuum svemira?' },
      options: [ { en: 'Yes, explosions are loud enough', hr: 'Da, eksplozije su dovoljno glasne' }, { en: 'Yes, but only the low tones', hr: 'Da, ali samo niske tonove' }, { en: 'No: sound needs a medium (air, water, metal) to travel, and a vacuum has nothing to vibrate', hr: 'Ne: zvuku treba sredstvo (zrak, voda, metal) kojim se širi, a u vakuumu nema ničega što bi titralo' }, { en: 'No, because space is too cold', hr: 'Ne, jer je svemir prehladan' } ],
      answer: 2,
      explain: { en: 'Sound is a vibration passed from particle to particle. In a vacuum there are no particles, so there is no sound. Light, however, needs no medium, so the astronaut would see the flash in complete silence.',
                 hr: 'Zvuk je titranje koje se prenosi s čestice na česticu. U vakuumu nema čestica, pa nema ni zvuka. Svjetlosti, naprotiv, ne treba sredstvo, pa bi astronaut vidio bljesak u potpunoj tišini.' },
      misconception: { en: 'Films add sound in space for drama. "In space no one can hear you scream" is the correct physics.',
                       hr: 'Filmovi dodaju zvuk u svemiru radi dramatičnosti. "U svemiru nitko ne čuje tvoj vrisak" fizikalno je točno.' } },

    { id: 'rank-sound-speed', topic: 'waves', type: 'rank', level: 2,
      q: { en: 'Rank from the fastest to the slowest: the speed of sound in these materials.', hr: 'Poredaj od najveće do najmanje: brzina zvuka u ovim sredstvima.' },
      items: [ { en: 'steel', hr: 'čelik' }, { en: 'water', hr: 'voda' }, { en: 'air', hr: 'zrak' } ],
      explain: { en: 'Sound travels faster where the particles are closer together and more tightly bound: about 5000 m/s in steel, 1500 m/s in water and 340 m/s in air. That is why you hear a train through the rails before you hear it through the air.',
                 hr: 'Zvuk putuje brže gdje su čestice bliže i čvršće povezane: oko 5000 m/s u čeliku, 1500 m/s u vodi i 340 m/s u zraku. Zato vlak čuješ kroz tračnice prije nego kroz zrak.' } },

    { id: 'estimate-thunder-distance', topic: 'waves', type: 'num', level: 1,
      q: { en: 'You see a flash of lightning and hear the thunder 3 s later. How far away was the lightning, in metres? The speed of sound is 340 m/s; the light arrives practically instantly.',
           hr: 'Vidiš bljesak munje, a grmljavinu čuješ 3 s kasnije. Koliko je munja bila udaljena, u metrima? Brzina zvuka je 340 m/s; svjetlost stiže praktički odmah.' },
      answer: 1020, min: 900, max: 1200, unit: 'm',
      explain: { en: 's = v · t = 340 m/s · 3 s = 1020 m, roughly 1 km. Rule of thumb: every 3 s between flash and thunder means about 1 km of distance.',
                 hr: 's = v · t = 340 m/s · 3 s = 1020 m, otprilike 1 km. Pravilo: svake 3 s između bljeska i grmljavine znače oko 1 km udaljenosti.' } },

    /* ---------- LIGHT / SVJETLOST ---------- */
    { id: 'see-by-reflected-light', topic: 'light', type: 'mc', level: 1,
      q: { en: 'Why can you see a red apple lying on the table?', hr: 'Zašto možeš vidjeti crvenu jabuku koja leži na stolu?' },
      options: [ { en: 'Our eyes send out rays that touch the apple', hr: 'Naše oči šalju zrake koje dotaknu jabuku' }, { en: 'Light from the lamp reflects off the apple and enters our eyes', hr: 'Svjetlost iz lampe odbija se od jabuke i ulazi u naše oči' }, { en: 'The apple glows red by itself', hr: 'Jabuka sama svijetli crveno' }, { en: 'Red colour flows from the apple to the eye without light', hr: 'Crvena boja teče od jabuke do oka bez svjetlosti' } ],
      answer: 1,
      explain: { en: 'Objects that are not light sources are seen only because light from a source bounces off them into our eyes. The apple absorbs most colours and reflects mainly red. In a totally dark room you see nothing, however long you wait.',
                 hr: 'Tijela koja nisu izvori svjetlosti vidimo samo zato što se svjetlost nekog izvora odbija od njih u naše oči. Jabuka upija većinu boja, a odbija uglavnom crvenu. U potpuno tamnoj sobi ne vidiš ništa, koliko god dugo čekao.' },
      misconception: { en: 'The "eyes send out rays" idea is ancient (Euclid believed it) and still common. Light goes into the eye, not out of it.',
                       hr: 'Ideja da "oči šalju zrake" vrlo je stara (vjerovao je u nju i Euklid) i još uvijek česta. Svjetlost ulazi u oko, a ne izlazi iz njega.' } },

    { id: 'estimate-light-nanosecond', topic: 'light', type: 'num', level: 3,
      q: { en: 'Light travels 300 000 km in one second. How far does it travel in one nanosecond (one billionth of a second)? Answer in cm.',
           hr: 'Svjetlost u jednoj sekundi prijeđe 300 000 km. Koliko prijeđe u jednoj nanosekundi (milijarditom dijelu sekunde)? Odgovori u cm.' },
      answer: 30, min: 28, max: 32, unit: 'cm',
      explain: { en: '300 000 km/s = 300 000 000 m/s. In 0.000000001 s light covers 300 000 000 · 0.000000001 m = 0.3 m = 30 cm, about the length of a ruler. Computer engineers call a nanosecond "a light-foot".',
                 hr: '300 000 km/s = 300 000 000 m/s. U 0,000000001 s svjetlost prijeđe 300 000 000 · 0,000000001 m = 0,3 m = 30 cm, otprilike duljinu ravnala. Računalni inženjeri nanosekundu zovu "svjetlosnom stopom".' } },

    /* ---------- SPACE / SVEMIR ---------- */
    { id: 'moon-phases-not-shadow', topic: 'space', type: 'mc', level: 1,
      q: { en: 'Why do we sometimes see the Moon as a thin crescent?', hr: 'Zašto Mjesec ponekad vidimo kao uski srp?' },
      options: [ { en: 'Earth\'s shadow falls on the Moon', hr: 'Zemljina sjena pada na Mjesec' }, { en: 'Clouds cover part of the Moon', hr: 'Oblaci pokrivaju dio Mjeseca' }, { en: 'We see only the sunlit half of the Moon, and from Earth we look at it from the side', hr: 'Vidimo samo Suncem osvijetljenu polovicu Mjeseca, a sa Zemlje je gledamo sa strane' }, { en: 'The Moon shrinks and grows', hr: 'Mjesec se smanjuje i raste' } ],
      answer: 2,
      explain: { en: 'The Sun always lights exactly half of the Moon. As the Moon orbits Earth, we see that lit half from different angles: full, half, crescent. Earth\'s shadow falls on the Moon only during a lunar eclipse, a few times a year, and that looks quite different.',
                 hr: 'Sunce uvijek osvjetljava točno polovicu Mjeseca. Dok Mjesec kruži oko Zemlje, tu osvijetljenu polovicu vidimo iz različitih kutova: pun Mjesec, polovica, srp. Zemljina sjena pada na Mjesec samo za pomrčine Mjeseca, nekoliko puta godišnje, i to izgleda posve drukčije.' },
      misconception: { en: 'The "Earth\'s shadow" explanation is given by most adults too. Check: at half moon the Sun, Earth and Moon form a right angle, so Earth\'s shadow is nowhere near the Moon.',
                       hr: 'Objašnjenje "Zemljina sjena" daje i većina odraslih. Provjeri: kod polovice Mjeseca Sunce, Zemlja i Mjesec čine pravi kut, pa Zemljina sjena nije ni blizu Mjeseca.' } },

    { id: 'rank-weights-moon-earth-jupiter', topic: 'space', type: 'rank', level: 1,
      q: { en: 'The same 10 kg suitcase is weighed on four worlds. Rank from the largest weight to the smallest.',
           hr: 'Isti kovčeg mase 10 kg važemo na četiri nebeska tijela. Poredaj od najveće težine do najmanje.' },
      items: [ { en: 'on Jupiter', hr: 'na Jupiteru' }, { en: 'on Earth', hr: 'na Zemlji' }, { en: 'on Mars', hr: 'na Marsu' }, { en: 'on the Moon', hr: 'na Mjesecu' } ],
      explain: { en: 'Weight = m · g, and g differs: Jupiter about 25 N/kg (250 N), Earth 10 N/kg (100 N), Mars 3.7 N/kg (37 N), the Moon 1.6 N/kg (16 N). The mass, 10 kg, is the same everywhere.',
                 hr: 'Težina = m · g, a g se razlikuje: Jupiter oko 25 N/kg (250 N), Zemlja 10 N/kg (100 N), Mars 3,7 N/kg (37 N), Mjesec 1,6 N/kg (16 N). Masa, 10 kg, svugdje je ista.' } },

    /* ---------- SCIENCE / KAKO ZNANOST RADI ---------- */
    { id: 'hypothesis-never-fully-proven', topic: 'science', type: 'mc', level: 2,
      q: { en: 'A hypothesis has passed 100 experiments. What can scientists say about it?', hr: 'Hipoteza je prošla 100 pokusa. Što znanstvenici o njoj mogu reći?' },
      options: [ { en: 'It is proven true forever', hr: 'Dokazana je zauvijek' }, { en: 'It is well supported, but a single clear failed prediction could still overturn it', hr: 'Dobro je potkrijepljena, ali jedno jasno neuspjelo predviđanje još je uvijek može srušiti' }, { en: 'It is now a theory and cannot be changed', hr: 'Sad je teorija i ne može se mijenjati' }, { en: 'It is still a guess; 100 tests mean nothing', hr: 'Još je uvijek nagađanje; 100 provjera ne znači ništa' } ],
      answer: 1,
      explain: { en: 'Science supports ideas with evidence but cannot prove them beyond all doubt: a hypothesis that survives many tests becomes trusted, yet a black swan can always appear. That is not a weakness; it is what lets science correct itself.',
                 hr: 'Znanost ideje potkrepljuje dokazima, ali ih ne može dokazati bez ikakve sumnje: hipotezi koja preživi mnogo provjera vjerujemo, ali crni labud uvijek se može pojaviti. To nije slabost; upravo to znanosti omogućuje da se sama ispravlja.' },
      misconception: { en: 'People think "scientifically proven" means "certain". Scientific knowledge is reliable precisely because it stays open to testing.',
                       hr: 'Ljudi misle da "znanstveno dokazano" znači "sigurno". Znanstveno znanje pouzdano je upravo zato što ostaje otvoreno provjeri.' } },

    { id: 'estimate-heartbeats-day', topic: 'science', type: 'num', level: 2,
      q: { en: 'Estimate how many times your heart beats in one day. (Hint: count your pulse for a minute first.)',
           hr: 'Procijeni koliko puta tvoje srce otkuca u jednom danu. (Savjet: najprije izbroji puls u jednoj minuti.)' },
      answer: 100000, min: 70000, max: 150000, unit: '',
      explain: { en: 'A resting heart beats about 70 times a minute. A day has 24 · 60 = 1440 minutes, so about 70 · 1440 ≈ 100 000 beats. Anything between 70 000 and 150 000 is a reasonable estimate, depending on the pulse you assume.',
                 hr: 'Srce u mirovanju otkuca oko 70 puta u minuti. Dan ima 24 · 60 = 1440 minuta, pa je to oko 70 · 1440 ≈ 100 000 otkucaja. Sve između 70 000 i 150 000 razumna je procjena, ovisno o pulsu koji pretpostaviš.' } }
  ]);
})();
